struct import_t* get_import_symbols(struct MACH0_(obj_t)* bin) {
    uint32_t i, nundef;
    struct import_t* imports = NULL;
    struct symt_t* sym = NULL;

    if (!bin || !bin->str || !bin->sym || !bin->nsym)
        return NULL;

    nundef = 0;
    for (i = 0; i < bin->nsym; i++) {
        if (MACH0_(sym)(bin, i)->n_type & N_UNDF)
            nundef++;
    }

    imports = (struct import_t*)malloc(sizeof(struct import_t) * (nundef + 1));
    if (!imports)
        return NULL;

