struct import_t* get_import_symbols(struct MACH0_(obj_t)* bin) {
    if (!bin || !bin->symtab) {
        return NULL;
    }

    uint32_t num_undef = bin->symtab->nundef;
    struct import_t* imports = calloc(num_undef, sizeof(struct import_t));
    if (!imports) {
        return NULL;
    }

    for (uint32_t i = 0; i < num_undef; i++) {
        const char* name = MACH0_(sym_get_name)(bin, i);
        if (!name) {
            continue;
        }

        // Filter and duplicate the symbol name if valid
        char* filtered_name = strdup(name);
        if (!filtered_name) {
            // Clean up previously allocated memory before returning
            for (uint32_t j = 0; j < i; j++) {
                free(imports[j].name);
            }
            free(imports);
            return NULL;
        }

        imports[i].name = filtered_name;
    }

    bin->numimports = num_undef;
    bin->imports = imports;
    return imports;
}

