struct import_t* get_import_symbols(struct MACH0_(obj_t)* bin) {
    uint32_t i, import_count = 0;
    struct import_t* imports = NULL;

    if (!bin || !bin->nb_unsym || !bin->unsym) {
        return NULL;
    }

    imports = (struct import_t*)malloc(bin->nb_unsym * sizeof(struct import_t));
    if (!imports) {
        return NULL;
    }

    for (i = 0; i < bin->nb_unsym; i++) {
        const char* name = bin->unsym[i].name;

        if (!name) {
            continue;
        }

        imports[import_count].name = strdup(name);
        if (!imports[import_count].name) {
            return NULL;
        }
        import_count++;
    }

    bin->nb_imports = import_count;
    return imports;
}
